def is_safe(queens, row, col):
    for r in range(row):
        c = queens[r]
        if c == col or abs(c - col) == abs(r - row):
            return False
    return True

def solve_n_queens(n):
    queens = [-1] * n
    def backtrack(row):
        if row == n:
            return True
        for col in range(n):
            if is_safe(queens, row, col):
                queens[row] = col
                if backtrack(row + 1):
                    return True
                queens[row] = -1
        return False

    if backtrack(0):
        return queens
    else:
        return None

solution = solve_n_queens(8)
print(solution)
